import os, glob, re, json
d = os.environ['RLM_SESSION_DIR']
session_file = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')

with open(session_file, 'r') as f:
    lines = f.readlines()

# Parse all messages to find grids
G = {}  # task_id -> {input/output grids}
pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'

for line in lines:
    match = re.search(pattern, line)
    if match:
        kind, task_id, h, w = match.groups()
        G[(task_id, kind)] = (h, w)

print("Task grids found by type:")
for k, (h, w) in sorted(G.items()):
    print(f"  {k}: {h}x{w}")

# Look for task-efc2fba8
task = "task-efc2fba8"
print(f"\nLooking for task-{task}:")
for k in sorted(G.keys()):
    if task_id := k[0].startswith(task) if isinstance(k[0], str) else False:
        print(f"  {k}")

# Find task in its raw form
for k in G:
    if 'efc2fba8' in k[0]:
        print(f"Found: {k[0]}")

